fn skinInputMatrix(address: u32) -> mat4x4<f32> {
  return mat4x4<f32>(
    bitcast<vec4<f32>>(vec4<u32>(sceneInputs[address], sceneInputs[address+1u], sceneInputs[address+2u], sceneInputs[address+3u])),
    bitcast<vec4<f32>>(vec4<u32>(sceneInputs[address+4u], sceneInputs[address+5u], sceneInputs[address+6u], sceneInputs[address+7u])),
    bitcast<vec4<f32>>(vec4<u32>(sceneInputs[address+8u], sceneInputs[address+9u], sceneInputs[address+10u], sceneInputs[address+11u])),
    bitcast<vec4<f32>>(vec4<u32>(sceneInputs[address+12u], sceneInputs[address+13u], sceneInputs[address+14u], sceneInputs[address+15u])));
