fn skinPageAddress(root: u32, key: u32) -> u32 {
  var address = root;
  for (var shift = 24i; shift >= 0i; shift -= 8i) {
    if (address == 0xffffffffu) { return address; }
    address = sceneInputs[address + ((key >> u32(shift)) & 255u)];
  }
  return address;
}
fn skinRowAddress(root: u32, space: u32, key: u32) -> u32 {
  return skinPageAddress(skinPageAddress(root, space), key);
}


struct SkinDemandConstants {
  currentRoot: u32,
  previousRoot: u32,
  candidateCount: u32,
  hashCapacity: u32,
  counterBase: u32,
  descriptorBase: u32,
  rosterBase: u32,
  paletteBase: u32,
  jointCapacity: u32,
  rosterCapacity: u32,
  dispatchBase: u32,
  maxWorkgroups: u32,
