// Clear only the previous compact demand roster. A separate reset dispatch
// follows this pass; clearing the count in this dispatch would race readers.
@compute @workgroup_size(64)
fn clearSkinDemand(@builtin(global_invocation_id) id: vec3<u32>, @builtin(num_workgroups) groups: vec3<u32>) {
  let index = id.x + id.y * groups.x * 64u;
  let count = min(atomicLoad(&counters[view.skin.counterBase]), view.skin.rosterCapacity);
  if (index >= count) { return; }
  let hashSlot = visibleIndices[view.skin.rosterBase + index].x;
  atomicStore(&counters[view.skin.counterBase + 4u + hashSlot], 0u);
  visibleIndices[view.skin.descriptorBase + hashSlot] = vec4<u32>(0u);
}

@compute @workgroup_size(1)
fn resetSkinDemand() {
  atomicStore(&counters[view.skin.counterBase], 0u);
  atomicStore(&counters[view.skin.counterBase + 1u], 0u);
  atomicStore(&counters[view.skin.counterBase + 2u], 0u);
}

// Transient occupant of a hash location while its first claimant publishes the
// key. It is never a key: the claim rejects the one Scene slot that maps to it.
const SKIN_DEMAND_CLAIMING = 0xffffffffu;

// No workgroup waits for another claimant: collisions have a finite probe
// bound. Later dispatches, rather than spinning, consume completed descriptors.
// An empty location is acquired with atomicExchange. The compare-exchange
// builtin is deliberately absent: WebKit's Metal translation of it does not
// compile on iOS (its result struct is instantiated with an address-space
// qualified type), which stops the whole renderer at the first skinned frame.
@compute @workgroup_size(64)
fn claimSkinDemand(@builtin(global_invocation_id) id: vec3<u32>, @builtin(num_workgroups) groups: vec3<u32>) {
  let index = id.x + id.y * groups.x * 64u;
  if (index >= view.skin.candidateCount) { return; }
  // Every actual candidate writes its own reference. Raster/cull reads this
  // directly via the unchanged visible.z candidate identity, never a hash probe.
  let candidateBase = view.skin.rosterBase + view.skin.rosterCapacity;
  visibleIndices[candidateBase + index] = vec4<u32>(0xffffffffu, 0u, 0u, 0u);
  let slot = skinDemandCandidateSlot(index);
  // slot + 1 is the stored key; the slot whose key equals the transient marker
  // cannot own a Binding row and is rejected with the absent slot.
  if (slot >= SKIN_DEMAND_CLAIMING - 1u) { return; }
  let binding = skinRowAddress(view.skin.currentRoot, 1u, slot);
  if (binding == 0xffffffffu) { return; }
  let count = sceneInputs[binding];
  if (count == 0u) { return; }
  let key = slot + 1u;
  var hashSlot = (slot * 0x9e3779b9u) & (view.skin.hashCapacity - 1u);
  for (var probe = 0u; probe < view.skin.hashCapacity; probe++) {
    let location = view.skin.counterBase + 4u + hashSlot;
    // Only an observed-empty location is written. Exactly one invocation
    // exchanges the empty value out and publishes its key; an invocation that
    // exchanged out a published key restores it, and nothing else writes a
    // location that holds the marker, so no published key is ever lost.
    var occupant = atomicLoad(&counters[location]);
    var acquired = false;
    if (occupant == 0u) {
      occupant = atomicExchange(&counters[location], SKIN_DEMAND_CLAIMING);
      if (occupant == 0u) {
        atomicStore(&counters[location], key);
        acquired = true;
      } else if (occupant != SKIN_DEMAND_CLAIMING) {
        atomicStore(&counters[location], occupant);
      }
    }
    if (acquired) {
      visibleIndices[candidateBase + index].x = hashSlot;
      let demand = atomicAdd(&counters[view.skin.counterBase], 1u);
      if (demand >= view.skin.rosterCapacity) {
        atomicStore(&counters[view.skin.counterBase + 2u], 1u);
        return;
      }
      // Every acquired key is retained for sparse clear, including a rejected
      // palette allocation. Every key owns a joint, so rosterCapacity >= keys.
      visibleIndices[view.skin.rosterBase + demand] = vec4<u32>(hashSlot, 0u, 0u, 0u);
      let joints = atomicAdd(&counters[view.skin.counterBase + 1u], count);
      if (joints > view.skin.jointCapacity || count > view.skin.jointCapacity - joints) {
        atomicStore(&counters[view.skin.counterBase + 2u], 1u);
        return;
      }
      // Descriptor = complete key, joint count, vec4 palette base, valid flags.
      // Palette addresses never replace persistent Instance/customData fields.
      visibleIndices[view.skin.descriptorBase + hashSlot] = vec4<u32>(key, count, view.skin.paletteBase + joints * 8u, 0u);
      return;
    }
    if (occupant == key) {
      visibleIndices[candidateBase + index].x = hashSlot;
      return;
    }
    // A location seen mid-claim is read again in the same bounded iteration;
    // its claimant publishes without waiting on anyone, so this never spins on
    // a producer. Any other occupant is a different key: probe the next one.
    if (occupant != SKIN_DEMAND_CLAIMING) { hashSlot = (hashSlot + 1u) & (view.skin.hashCapacity - 1u); }
  }
  atomicStore(&counters[view.skin.counterBase + 2u], 1u);
}

// Separate from claim: every descriptor and the compact count is complete.
// The host admits rosterCapacity <= maxWorkgroups squared before any dispatch.
@compute @workgroup_size(1)
fn finalizeSkinDemand() {
  var count = min(atomicLoad(&counters[view.skin.counterBase]), view.skin.rosterCapacity);
  if (atomicLoad(&counters[view.skin.counterBase + 2u]) != 0u) { count = 0u; }
  indirectArgs[view.skin.dispatchBase] = max(1u, min(count, view.skin.maxWorkgroups));
  indirectArgs[view.skin.dispatchBase + 1u] = max(1u, (count + view.skin.maxWorkgroups - 1u) / view.skin.maxWorkgroups);
  indirectArgs[view.skin.dispatchBase + 2u] = 1u;
}

