var<workgroup> skinDemandHashSlot: u32;
var<workgroup> skinDemandBinding: u32;
var<workgroup> skinDemandSkeleton: u32;
var<workgroup> skinDemandPose: u32;
var<workgroup> skinDemandPreviousPose: u32;
