fn skinDemandDescriptor(candidateIndex: u32) -> vec4<u32> {
  if (candidateIndex >= view.skin.candidateCount) { return vec4<u32>(0u); }
  let candidateBase = view.skin.rosterBase + view.skin.rosterCapacity;
  let hashSlot = visibleIndices[candidateBase + candidateIndex].x;
  if (hashSlot >= view.skin.hashCapacity) { return vec4<u32>(0u); }
  return visibleIndices[view.skin.descriptorBase + hashSlot];
}

// Integer exponent tests: WGSL implementations may assume float comparisons
// never observe Inf/NaN and fold them away.
fn skinDemandFiniteColumn(column: vec4<f32>) -> bool {
  return all((bitcast<vec4<u32>>(column) & vec4<u32>(0x7fffffffu)) <= vec4<u32>(0x7f7fffffu));
}
fn skinDemandFinite(matrix: mat4x4<f32>) -> bool {
  return skinDemandFiniteColumn(matrix[0]) && skinDemandFiniteColumn(matrix[1]) &&
    skinDemandFiniteColumn(matrix[2]) && skinDemandFiniteColumn(matrix[3]);
}

fn skinDemandWriteMatrix(base: u32, matrix: mat4x4<f32>) {
  visibleIndices[base] = bitcast<vec4<u32>>(matrix[0]);
  visibleIndices[base + 1u] = bitcast<vec4<u32>>(matrix[1]);
  visibleIndices[base + 2u] = bitcast<vec4<u32>>(matrix[2]);
  visibleIndices[base + 3u] = bitcast<vec4<u32>>(matrix[3]);
}

// Lane 0 resolves the shared Binding/Skeleton rows and the Binding's whole
// pose rows. Composition and finiteness are checked by the lanes that write
// each joint, so a complete pose costs no serial walk over all joints.
@compute @workgroup_size(64)
fn resolveSkinDemand(@builtin(workgroup_id) id: vec3<u32>, @builtin(num_workgroups) groups: vec3<u32>, @builtin(local_invocation_index) lane: u32) {
  let demandIndex = id.x + id.y * groups.x;
  if (lane == 0u) {
    skinDemandAvailable = false;
    skinDemandHistory = false;
    atomicStore(&skinDemandMissing, 0u);
    atomicStore(&skinDemandMissingHistory, 0u);
    atomicStore(&skinDemandInvalid, 0u);
    atomicStore(&skinDemandInvalidHistory, 0u);
    if (demandIndex < min(atomicLoad(&counters[view.skin.counterBase]), view.skin.rosterCapacity) &&
        atomicLoad(&counters[view.skin.counterBase + 2u]) == 0u) {
      skinDemandHashSlot = visibleIndices[view.skin.rosterBase + demandIndex].x;
      skinDemandRow = visibleIndices[view.skin.descriptorBase + skinDemandHashSlot];
      let slot = skinDemandRow.x - 1u;
      let binding = skinRowAddress(view.skin.currentRoot, 1u, slot);
      if (binding != 0xffffffffu) {
        let count = sceneInputs[binding];
        let skeletonKey = sceneInputs[binding + 2u];
        let skeleton = skinRowAddress(view.skin.currentRoot, 0u, skeletonKey);
        let pose = skinRowAddress(view.skin.currentRoot, 2u, slot);
        if (skeleton != 0xffffffffu && sceneInputs[skeleton] == count && count > 0u) {
          skinDemandBinding = binding;
          skinDemandSkeleton = skeleton;
          skinDemandAvailable = true;
          // A missing or stale-extent pose is not a complete pose.
          if (pose == 0xffffffffu || sceneInputs[pose] != count) { atomicStore(&skinDemandMissing, 1u); }
          skinDemandPose = pose;
          // Both roots are retained by one arena: equal row addresses denote the
          // exact immutable Binding/Skeleton versions in the previous frame.
          skinDemandHistory =
            skinRowAddress(view.skin.previousRoot, 1u, slot) == binding &&
            skinRowAddress(view.skin.previousRoot, 0u, skeletonKey) == skeleton;
          if (skinDemandHistory) {
            let before = skinRowAddress(view.skin.previousRoot, 2u, slot);
            if (before == 0xffffffffu || sceneInputs[before] != count) { atomicStore(&skinDemandMissingHistory, 1u); }
            skinDemandPreviousPose = before;
          }
        }
      }
    }
  }
  workgroupBarrier();
  // Pose presence is uniform per Binding: skip all reads when current is missing.
  let available = workgroupUniformLoad(&skinDemandAvailable) && atomicLoad(&skinDemandMissing) == 0u;
  if (available) {
    let zero = mat4x4<f32>(vec4<f32>(0.0), vec4<f32>(0.0), vec4<f32>(0.0), vec4<f32>(0.0));
    let count = sceneInputs[skinDemandBinding];
    let pose = skinDemandPose;
    let before = skinDemandPreviousPose;
    let history = skinDemandHistory && atomicLoad(&skinDemandMissingHistory) == 0u;
    for (var index = lane; index < skinDemandRow.y; index += 64u) {
      var current = zero;
      var previous = zero;
      if (index < count) {
        let inverse = skinInputMatrix(skinDemandSkeleton + 1u + index * 16u);
        current = skinInputMatrix(pose + 1u + index * 16u) * inverse;
        previous = current;
        if (history) { previous = skinInputMatrix(before + 1u + index * 16u) * inverse; }
      }
      if (!skinDemandFinite(current)) { atomicStore(&skinDemandInvalid, 1u); }
      if (!skinDemandFinite(previous)) { atomicStore(&skinDemandInvalidHistory, 1u); }
      skinDemandWriteMatrix(skinDemandRow.z + index * 4u, current);
      skinDemandWriteMatrix(skinDemandRow.z + (skinDemandRow.y + index) * 4u, previous);
    }
  }
  workgroupBarrier();
  // A missing current joint is not a complete pose: no flags are published.
  if (available && atomicLoad(&skinDemandMissing) == 0u) {
    let invalid = atomicLoad(&skinDemandInvalid);
    let history = skinDemandHistory && atomicLoad(&skinDemandMissingHistory) == 0u;
    // Seed the complete previous pose from current when history is absent,
    // incomplete or not representable; no compatible prefix survives.
    let resetHistory = (skinDemandHistory && !history) || atomicLoad(&skinDemandInvalidHistory) != 0u;
    if (resetHistory) {
      for (var index = lane; index < skinDemandRow.y; index += 64u) {
        let currentBase = skinDemandRow.z + index * 4u;
        let previousBase = currentBase + skinDemandRow.y * 4u;
        for (var column = 0u; column < 4u; column++) { visibleIndices[previousBase + column] = visibleIndices[currentBase + column]; }
      }
    }
    if (lane == 0u) {
      visibleIndices[view.skin.descriptorBase + skinDemandHashSlot].w =
        select(0u, 1u | select(0u, 2u, history && !resetHistory), invalid == 0u);
    }
  }
}


struct SkinEnvelopeBounds {
  minimum: vec3<f32>,
  valid: u32,
  maximum: vec3<f32>,
};

fn skinEnvelopeInput(at: u32) -> vec4<f32> {
  return bitcast<vec4<f32>>(vec4<u32>(sceneInputs[at], sceneInputs[at + 1u], sceneInputs[at + 2u], sceneInputs[at + 3u]));
}

// Reject source subnormals before bitcasting. Compute and vertex operations
// may legally flush differently, and a later large factor can amplify that gap.
fn skinEnvelopeUnstable(words: vec4<u32>) -> bool {
  let magnitude = words & vec4<u32>(0x7fffffffu);
  return any((magnitude - vec4<u32>(1u)) < vec4<u32>(0x007fffffu)) ||
    any(magnitude > vec4<u32>(0x7f7fffffu));
}

fn skinEnvelopeInputUnstable(at: u32) -> bool {
  return skinEnvelopeUnstable(vec4<u32>(sceneInputs[at], sceneInputs[at + 1u], sceneInputs[at + 2u], sceneInputs[at + 3u]));
}

fn skinEnvelopeMatrix(at: u32) -> mat4x4<f32> {
  return mat4x4<f32>(bitcast<vec4<f32>>(visibleIndices[at]), bitcast<vec4<f32>>(visibleIndices[at + 1u]),
    bitcast<vec4<f32>>(visibleIndices[at + 2u]), bitcast<vec4<f32>>(visibleIndices[at + 3u]));
}

fn skinEnvelopeBounds(geometry: u32, paletteBase: u32, jointCount: u32, displacementRadius: f32) -> SkinEnvelopeBounds {
  var result = SkinEnvelopeBounds(vec3<f32>(0.0), 0u, vec3<f32>(0.0));
  if (geometry == 0u || geometry == 0xffffffffu) { return result; }
  let maximumFloat = bitcast<f32>(0x7f7fffffu);
  // The material owner supplies its qualified local displacement bound. NaN
  // (unknown), negative and infinite bounds never grant culling permission.
  if (!(displacementRadius >= 0.0) || !(displacementRadius <= maximumFloat)) { return result; }
  if (skinEnvelopeInputUnstable(geometry)) { return result; }
  let header = skinEnvelopeInput(geometry);
  // A received zero may be a flushed positive subnormal material radius.
  let radius = displacementRadius + bitcast<f32>(0x00800000u);
  if (header.x < bitcast<f32>(0x00800000u) || header.y < header.x || header.z > f32(jointCount) || header.w < 1.0) { return result; }
  var minimum = vec3<f32>(maximumFloat);
  var maximum = vec3<f32>(-maximumFloat);
  var magnitude = 1.0;
  var localMagnitude = 1.0;
  for (var index = 0u; index < u32(header.w); index++) {
    let lowAt = geometry + 4u + index * 8u;
    if (skinEnvelopeInputUnstable(lowAt) || skinEnvelopeInputUnstable(lowAt + 4u)) { return result; }
    let low = skinEnvelopeInput(lowAt);
    let high = skinEnvelopeInput(lowAt + 4u);
    let localExtent = max(abs(low.xyz - vec3<f32>(radius)), abs(high.xyz + vec3<f32>(radius)));
    localMagnitude = max(localMagnitude, 1.0 + localExtent.x + localExtent.y + localExtent.z);
    let matrixAt = paletteBase + u32(low.w) * 4u;
    for (var row = 0u; row < 4u; row++) {
      let words = visibleIndices[matrixAt + row];
      if (skinEnvelopeUnstable(words)) { return result; }
      // Blending precedes position projection, so even an origin vertex cannot
      // qualify a coefficient whose weighted accumulation may overflow.
      let limit = maximumFloat / (1.0 + 64.0 * 0.00000011920928955078125) / max(1.0, header.y);
      if (any(abs(bitcast<vec4<f32>>(words)) > vec4<f32>(limit))) { return result; }
    }
    let matrix = skinEnvelopeMatrix(matrixAt);
    // The enclosure proof requires affine composed matrices and positive weights.
    if (matrix[0].w != 0.0 || matrix[1].w != 0.0 || matrix[2].w != 0.0 || matrix[3].w != 1.0) { return result; }
    var a = matrix[3].xyz;
    var b = a;
    var absolute = abs(a);
    for (var dimension = 0u; dimension < 3u; dimension++) {
      let first = matrix[dimension].xyz * (low[dimension] - radius);
      let second = matrix[dimension].xyz * (high[dimension] + radius);
      a += min(first, second);
      b += max(first, second);
      absolute += max(abs(first), abs(second));
    }
    if (!all(abs(a) <= vec3<f32>(maximumFloat)) || !all(abs(b) <= vec3<f32>(maximumFloat))) { return result; }
    minimum = min(minimum, a);
    maximum = max(maximum, b);
    magnitude = max(magnitude, max(absolute.x, max(absolute.y, absolute.z)));
  }
  // Four palette*weight products and their accumulation precede the vertex
  // dot product. Cover independent intermediate FTZ, including homogeneous
  // xyz/sum(weight): normal positive weights keep w >= exact weight sum / 4.
  let minimumNormal = bitcast<f32>(0x00800000u);
  let blendUnderflow = max(64.0 * minimumNormal, 256.0 * minimumNormal / header.x) * localMagnitude;
  let padding = 64.0 * 0.00000011920928955078125 * magnitude * max(1.0, header.y) + blendUnderflow;
  result.minimum = min(minimum, min(min(minimum * header.x, minimum * header.y), min(maximum * header.x, maximum * header.y))) - vec3<f32>(padding);
  result.maximum = max(maximum, max(max(minimum * header.x, minimum * header.y), max(maximum * header.x, maximum * header.y))) + vec3<f32>(padding);
  if (all(abs(result.minimum) <= vec3<f32>(maximumFloat)) && all(abs(result.maximum) <= vec3<f32>(maximumFloat))) { result.valid = 1u; }
  return result;
}

