fn skinEnvelopeInput(at: u32) -> vec4<f32> {
  return bitcast<vec4<f32>>(vec4<u32>(sceneInputs[at], sceneInputs[at + 1u], sceneInputs[at + 2u], sceneInputs[at + 3u]));
}

