fn skinEnvelopeUnstable(words: vec4<u32>) -> bool {
  let magnitude = words & vec4<u32>(0x7fffffffu);
  return any((magnitude - vec4<u32>(1u)) < vec4<u32>(0x007fffffu)) ||
    any(magnitude > vec4<u32>(0x7f7fffffu));
}

