    let matrix = skinEnvelopeMatrix(matrixAt);
    // The enclosure proof requires affine composed matrices and positive weights.
    if (matrix[0].w != 0.0 || matrix[1].w != 0.0 || matrix[2].w != 0.0 || matrix[3].w != 1.0) { return result; }
